    l = max(l, 2)

    # If l > r after adjustment, no numbers
    if l > r:
        return "0\n"

    # Sieve of Eratosthenes for range [l, r]
    limit = int(r**0.5) + 1
    if limit < 2:
        limit = 2

    # Find primes up to sqrt(r)
    is_prime_small = [True] * (limit + 1)
    is_prime_small[0] = is_prime_small[1] = False

