                    for r in range(r1, r2 + 1):
                        freq = {}
                        for c in range(c1, c2 + 1):
                            ch = ord(matrix[r][c]) - ord('a')
                            freq[ch] = freq.get(ch, 0) + 1

                        odd_count = sum(1 for f in freq.values() if f % 2 == 1)
                        if odd_count > 1:
