                            break

                    if not rows_ok:
                        continue

                    # Check if each column can be made palindrome (after row reordering)
                    # For columns to be palindrome-able, independence of row ordering means
                    # we just need each column's character multiset to allow palindrome formation
                    cols_ok = True
                    for c in range(c1, c2 + 1):
                        freq = {}
                        for r in range(r1, r2 + 1):
