            for j in range(26):
                prefix[i][c+1][j] = prefix[i][c][j] + (1 if j == ch else 0)
            for j in range(26):
                prefix[i][c+1][j] += prefix[i-1][c+1][j]

    ans = 0

    for r1 in range(n):
        for r2 in range(r1, n):
            for c1 in range(m):
                for c2 in range(c1, m):
                    # Count character occurrences in submatrix
                    odd_count = 0
                    for j in range(26):
                        count = prefix[r2+1][c2+1][j] - prefix[r1][c2+1][j] - \
                               prefix[r2+1][c1][j] + prefix[r1][c1][j]
                        if count % 2 == 1:
