        a = a % m
        if a == 0:
            return -1
        if a == 1:
            return 1
        phi = m - 1  # For prime m
        divisors = []
        d = 1
        while d * d <= phi:
            if phi % d == 0:
                divisors.append(d)
                if d * d != phi:
                    divisors.append(phi // d)
            d += 1
        for d in divisors:
            if pow(a, d, m) == 1:
