def solution(input_str):
    """
    Solve the Martian beads problem by finding the k-th lexicographically 
    smallest canonical string of length n.

    Equivalence relation: s is equivalent to its reverse, color complement,
    or both. Canonical form = lexicographically smallest in equivalence class.

    Parameters:
        input_str: string containing 'n k' (length and index)

    Returns:
        k-th canonical string with newline, or "-1" if impossible
    """
    n, k = map(int, input_str.strip().split())

    def complement(s):
        return ''.join('1' if c == '0' else '0' for c in s)

    def reverse(s):
        return s[::-1]

    def canonical(s):
        """Get the canonical (lexicographically smallest) form of string s"""
        transforms = [s, complement(s), reverse(s), reverse(complement(s))]
        return min(transforms)

    def count_canonical_strings(n_val):
        """Count canonical strings of length n_val by computing unique canonical forms"""
        canons = set()
        for i in range(1 << n_val):
            s = f"{i:0{n_val}b}"
            canons.add(canonical(s))
        return len(canons)

    def get_kth_canonical(n_val, k_val):
        """Get k-th canonical string of length n_val"""
        canons = []
        seen = set()
        for i in range(1 << n_val):
            s = f"{i:0{n_val}b}"
            c = canonical(s)
            if c not in seen:
                seen.add(c)
                canons.append(c)
                if len(canons) >= k_val:
                    return c
        return None

    # Count total canonical strings for given n
    total = count_canonical_strings(n)

    # The example suggests canonical count for n=4 is 5
    # 2^(n-1) approximates the number
    if k > total:
        return "-1"

    return get_kth_canonical(n, k) + "\n"


