def solution(input_str):
    MOD = 1_000_000_007
    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    n, m = map(int, lines[0].split())

    # Track clause occurrences for each variable
    var_occ = [[] for _ in range(m + 1)]
    for i in range(n):
        parts = list(map(int, lines[i+1].split()))
        for lit in parts[1:]:
            var_occ[abs(lit)].append(i)

    # Union-Find for clause components
    parent = list(range(n))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Join clauses that share variables
    for v in range(1, m + 1):
        occs = var_occ[v]
        for i in range(len(occs)):
            for j in range(i + 1, len(occs)):
                union(occs[i], occs[j])

    # For each component with k clauses, there are 2^(k-1) satisfying assignments
    # Variables appearing only once contribute factor of 2
    result = 1
    for i in range(n):
        if parent[i] == i:
            size = sum(1 for j in range(n) if find(j) == i)
            if size > 0:
                result = (result * pow(2, size - 1, MOD)) % MOD

    # Count free variables (appearing at most once)
    for v in range(1, m + 1):
        if len(var_occ[v]) <= 1:
            result = (result * 2) % MOD

    return str(result)
