        idx += m

    # Get all divisor pairs
    div_n = divisors(n)
    div_m = divisors(m)

    ans = []
    for r in div_n:
        for c in div_m:
            # Check if all r×c tiles are equal
            # Number of tile rows: n // r
            # Number of tile cols: m // c

            if r == n and c == m:
                # Only 1 tile, always valid
                ans.append((r, c))
